def error_absoluto(x_aprox, x_real):
    return abs(x_aprox - x_real)

def error_relativo(x_aprox, x_real):
    return abs(x_aprox - x_real) / abs(x_real)

real = 1.5213797068
aprox = 1.5213797

print(f"Error absoluto: {error_absoluto(aprox, real):.3e}")
print(f"Error relativo: {error_relativo(aprox, real):.3e}")

def biseccion(f, a, b, tol=1e-8, max_iter=100):
    fa, fb = f(a), f(b)
    if fa * fb >= 0:
        raise ValueError("Bolzano no se cumple")

    for k in range(1, max_iter + 1):
        c = (a + b) / 2
        fc = f(c)
        error = (b - a) / 2

        print(f"Iter {k:2d}: c = {c:.10f}  f(c) = {fc:+.3e}  err = {error:.3e}")

        if error < tol or fc == 0:
            return c, k

        if fa * fc < 0:
            b, fb = c, fc
        else:
            a, fa = c, fc

    raise RuntimeError("No convergió")

f = lambda x: x**3 - x - 2
raiz, iters = biseccion(f, 1, 2)
print(f"\nRaíz: {raiz:.10f}")
print(f"Iteraciones: {iters}")

# Ecuación: x³ - x - 1 = 0
# Reescribimos como x = g(x):
#
# x³ = x + 1
# x = (x + 1)^(1/3)

def g(x):
    return (x + 1) ** (1/3)

def dg(x):
    h = 1e-8
    return (g(x + h) - g(x - h)) / (2 * h)

# Verificar convergencia
print(f"g'(1.32) ≈ {abs(dg(1.32)):.4f}")
print("Converge" if abs(dg(1.32)) < 1 else "Diverge")

def g1(x):
    return x**3 - x  # ¡Diverge!

def g2(x):
    return (x + 1) ** (1/3)   # converge

def g3(x):
    return 1 + 1/x   # otra reescritura

# Verificar convergencia
h = 1e-8
for nombre, g in [('g1', g1), ('g2', g2), ('g3', g3)]:
    d = (g(1.32 + h) - g(1.32 - h)) / (2*h)
    print(f"{nombre}: |g'(1.32)| = {abs(d):.4f}  →  {'Converge' if abs(d) < 1 else 'Diverge'}")

import numpy as np

# Cálculo inestable: resta de números cercanos
def f_inestable(x):
    return x**2 - 1

def f_estable(x):
    return (x - 1) * (x + 1)

x = 1.0000001
print(f"Inestable: {f_inestable(x):.20e}")
print(f"Estable:   {f_estable(x):.20e}")
